#include <cstdint>
#include <format>
#include <iostream>
#include <latch>
#include <stop_token>
#include <thread>

int main() {
  std::latch running(1);
  std::int64_t noticed = 0;  // written only by the stop callback, on the thread that requests the stop
  std::int64_t rounds = 0;   // written only by the worker
  std::int64_t left_on_request = 0;
  {
    std::jthread worker([&running, &noticed, &rounds, &left_on_request](std::stop_token stop) {
      const std::stop_callback note(stop, [&noticed] { noticed = 1; });
      running.count_down();
      for (int k = 0; k < 1000; ++k) ++rounds;  // work that happens whatever the scheduler does
      while (!stop.stop_requested()) ++rounds;  // then poll until somebody asks it to finish
      left_on_request = stop.stop_requested() ? 1 : 0;
    });
    running.wait();
    std::cout << std::format("worker running, stop possible: {}\n", worker.get_stop_token().stop_possible());
  }  // the jthread destructor calls request_stop() and then join()

  std::cout << std::format("the callback ran: {}\n", noticed == 1);
  std::cout << std::format("the worker did its first 1000 rounds: {}\n", rounds >= 1000);
  std::cout << std::format("it left the loop because the stop was requested: {}\n", left_on_request == 1);
}

