#include <stop_token>
#include <thread>
#include <utility>

struct Command {
  std::int64_t id = 0;
};

// One waiting room that a stop token can empty, without a flag of its own.
class Inbox {
 public:
  void send(Command command) {
    {
      const std::lock_guard<std::mutex> lock(mutex_);
      items_.push_back(command);
    }
    arrived_.notify_one();
  }

  // No value only when the stop was requested and nothing is left: the queue drains first.
  [[nodiscard]] std::optional<Command> take(std::stop_token stop) {
    std::unique_lock<std::mutex> lock(mutex_);
    if (!arrived_.wait(lock, stop, [this] { return !items_.empty(); })) return std::nullopt;
    const Command command = items_.front();
    items_.pop_front();
    return command;
  }

 private:
  std::mutex mutex_;
  std::condition_variable_any arrived_;  // _any, because only this one takes a stop token
  std::deque<Command> items_;
};

int main() {
  Inbox inbox;
  std::int64_t received = 0;
  std::int64_t sum = 0;
  {
    std::jthread driver([&inbox, &received, &sum](std::stop_token stop) {
      while (const std::optional<Command> command = inbox.take(stop)) {
        ++received;
        sum += command.value().id;
      }
    });
    inbox.send({.id = 10});
    inbox.send({.id = 32});
  }  // ~jthread requests the stop, which ends the wait once the inbox is empty

  std::cout << std::format("commands received {}, sum {}\n", received, sum);
}

