#include <optional>
#include <ranges>
#include <stop_token>
#include <thread>
#include <utility>
#include <vector>

struct Job {
  std::int64_t id = 0;
};

// A bounded queue of jobs and the threads that run them. Shutdown comes in two flavours:
// close_and_drain() finishes what was accepted, and cancel() stops and discards the rest.
class WorkerPool {
 public:
  using Handler = std::function<void(Job)>;

  WorkerPool(std::ptrdiff_t workers, std::ptrdiff_t capacity, Handler handler)
      : capacity_(capacity), handler_(std::move(handler)) {
    workers_.reserve(workers);
    for (std::ptrdiff_t i = 0; i < workers; ++i) {
      workers_.emplace_back([this](std::stop_token stop) { run(stop); });
    }
  }

  WorkerPool(const WorkerPool&) = delete;
  WorkerPool& operator=(const WorkerPool&) = delete;
  WorkerPool(WorkerPool&&) = delete;
  WorkerPool& operator=(WorkerPool&&) = delete;

  ~WorkerPool() { cancel(); }

  // Stop the workers where they are, discard what nobody will run, and join. Calling it twice is harmless.
  void cancel() {
    for (std::jthread& worker : workers_) worker.request_stop();
    {
      const std::lock_guard<std::mutex> lock(mutex_);
      closed_ = true;
      dropped_ += std::ssize(jobs_);
      jobs_.clear();
    }
    has_job_.notify_all();
    has_room_.notify_all();
    for (std::jthread& worker : workers_) {
      if (worker.joinable()) worker.join();
    }
  }

  // False once the pool is closed; otherwise it waits for room.
  [[nodiscard]] bool submit(Job job) {
    {
      std::unique_lock<std::mutex> lock(mutex_);
      has_room_.wait(lock, [this] { return closed_ || std::ssize(jobs_) < capacity_; });
      if (closed_) return false;
      jobs_.push_back(job);
    }
    has_job_.notify_one();
    return true;
  }

  // Stop accepting, let the workers finish the queue, then join them.
  void close_and_drain() {
    {
      const std::lock_guard<std::mutex> lock(mutex_);
      closed_ = true;
    }
    has_job_.notify_all();
    has_room_.notify_all();
    for (std::jthread& worker : workers_) {
      if (worker.joinable()) worker.join();
    }
  }

  [[nodiscard]] std::int64_t done() const {
    const std::lock_guard<std::mutex> lock(mutex_);
    return done_;
  }
  [[nodiscard]] std::int64_t dropped() const {
    const std::lock_guard<std::mutex> lock(mutex_);
    return dropped_;
  }

 private:
  void run(std::stop_token stop) {
    while (true) {
      std::optional<Job> job;
      {
        std::unique_lock<std::mutex> lock(mutex_);
        has_job_.wait(lock, stop, [this] { return closed_ || !jobs_.empty(); });
        if (jobs_.empty()) return;          // closed and drained, or stopped with nothing left
        if (stop.stop_requested()) return;  // stopped with work left: cancel() counts it as dropped
        job = jobs_.front();
        jobs_.pop_front();
      }
      has_room_.notify_one();
      handler_(job.value());
      const std::lock_guard<std::mutex> lock(mutex_);
      ++done_;
    }
  }

  mutable std::mutex mutex_;
  std::condition_variable_any has_job_;  // _any: this one waits with a stop token
  std::condition_variable_any has_room_;
  std::deque<Job> jobs_;
  std::ptrdiff_t capacity_ = 0;
  bool closed_ = false;
  std::int64_t done_ = 0;
  std::int64_t dropped_ = 0;
  Handler handler_;
  std::vector<std::jthread> workers_;  // declared last: stopped and joined before anything above it goes
};

int main() {
  constexpr std::ptrdiff_t kWorkers = 4;
  constexpr std::ptrdiff_t kCapacity = 8;
  constexpr std::int64_t kJobs = 2000;

  // Draining: every accepted job runs.
  std::mutex seen_mutex;
  std::vector<std::int64_t> seen;
  {
    WorkerPool pool(kWorkers, kCapacity, [&seen_mutex, &seen](Job job) {
      const std::lock_guard<std::mutex> lock(seen_mutex);
      seen.push_back(job.id);
    });
    for (std::int64_t id = 0; id < kJobs; ++id) {
      if (!pool.submit({.id = id})) break;
    }
    pool.close_and_drain();
    std::cout << std::format("drain: {} submitted, {} done, {} dropped\n", kJobs, pool.done(), pool.dropped());
  }
  std::ranges::sort(seen);
  std::vector<std::int64_t> wanted(kJobs);
  std::iota(wanted.begin(), wanted.end(), 0);
  std::cout << std::format("drain: every job ran exactly once: {}\n", seen == wanted);

  // Discarding: the pool is cancelled, and nothing is left unaccounted for.
  std::int64_t accepted = 0;
  std::int64_t ran = 0;
  std::int64_t dropped = 0;
  {
    WorkerPool pool(kWorkers, kCapacity, [](Job) {});
    for (std::int64_t id = 0; id < kJobs; ++id) {
      if (pool.submit({.id = id})) ++accepted;
    }
    pool.cancel();  // what the destructor does, called here so the counters can be read afterwards
    ran = pool.done();
    dropped = pool.dropped();
  }
  std::cout << std::format("discard: {} accepted, every one of them either ran or was dropped: {}\n", accepted,
                           accepted == ran + dropped);
}

