#include <latch>
#include <stop_token>
#include <thread>
#include <vector>

// Releases the worker as it is destroyed, and waits for it to touch the samples one last time.
struct Gate {
  std::latch go{1};
  std::latch done{1};
  ~Gate() {
    go.count_down();
    done.wait();
  }
};

class Monitor {
 public:
  Monitor() {
    worker_ = std::jthread([this](std::stop_token stop) { run(stop); });
  }

 private:
  void run(std::stop_token stop) {
    gate_.go.wait();  // pinned to the moment the members are being destroyed
    if (!stop.stop_requested()) total_ += static_cast<std::int64_t>(samples_.front());
    gate_.done.count_down();
  }

  std::jthread worker_;  // wrong: declared first, so it is destroyed last, after the data it reads
  Gate gate_;
  std::vector<int> samples_ = std::vector<int>(1000, 7);
  std::int64_t total_ = 0;
};

int main() {
  { Monitor monitor; }
  std::cout << "monitor gone\n";
}

#include <cstdint>
#include <format>
