#include <thread>
#include <vector>

class Monitor {
 public:
  Monitor() {
    worker_ = std::jthread([this](std::stop_token stop) { run(stop); });
    running_.wait();  // the constructor returns with the worker already in its loop
  }

  [[nodiscard]] std::int64_t total() const { return total_; }  // call it after the worker has joined

 private:
  void run(std::stop_token stop) {
    running_.count_down();
    while (!stop.stop_requested()) total_ += static_cast<std::int64_t>(samples_.front());
  }

  std::vector<int> samples_ = std::vector<int>(1000, 7);
  std::latch running_{1};
  std::int64_t total_ = 0;
  std::jthread worker_;  // declared last, so it is stopped and joined before anything it reads is destroyed
};

int main() {
  Monitor monitor;
  // ~Monitor stops and joins the worker first, then destroys samples_.
  std::cout << "monitor built and running\n";
}

