int main() {
  std::thread logger([] {
    std::this_thread::sleep_for(std::chrono::seconds(1));
    std::cout << "the detached logger finished writing\n";  // never reached
  });
  logger.detach();
  std::cout << "main is leaving while the logger still has a second of work\n";
}
